def variants(S,h,w):
 # rotations and reflections in canonical box
 arr=np.zeros((h,w),int)
 for r,c in S: arr[r,c]=1
 out=[]
 for flip in [False,True]:
  a=arr[:,::-1] if flip else arr
  for k in range(4):
   b=np.rot90(a,k)
   out.append(b.astype(bool))
 return out

def iou_best_resize(cells, targetcells):
 S,sh,sw=normcells(cells);T,th,tw=normcells(targetcells)
 scores=[]
 for sv in variants(S,sh,sw):
  # stretch nearest to target
  for method in range(2):
   a=np.zeros((th,tw),bool)
   # mapping source occupied pixels to bins by nearest
   for r,c in np.argwhere(sv):
    if method==0:
     rr=min(th-1,int(r*th/sv.shape[0])); cc=min(tw-1,int(c*tw/sv.shape[1]))
    else:
     rr=min(th-1,round(r*(th-1)/max(1,sv.shape[0]-1)));cc=min(tw-1,round(c*(tw-1)/max(1,sv.shape[1]-1)))
    a[rr,cc]=1
   targ=np.zeros((th,tw),bool)
   for r,c in T:targ[r,c]=1
   inter=(a&targ).sum();union=(a|targ).sum()
   scores.append(inter/union if union else 0)
 return max(scores)
